create policy app_config_admin_insert on public.app_config for insert to authenticated with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy app_config_admin_update on public.app_config for update to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
create policy app_config_admin_delete on public.app_config for delete to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');
